package main

import (
	"crypto/subtle"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"
	"sync"
)

// ConfigStore represents a hierarchical configuration system
type ConfigStore struct {
	mu     sync.RWMutex
	data   map[string]interface{}
	schema map[string]string
}

var globalConfig = &ConfigStore{
	data: map[string]interface{}{
		"app": map[string]interface{}{
			"name":    "myservice",
			"version": "1.0.0",
		},
		"auth": map[string]interface{}{
			"enabled":  true,
			"provider": "internal",
		},
		"features": map[string]interface{}{
			"rateLimit": true,
			"logging":   true,
		},
	},
	schema: map[string]string{
		"app.name":       "string",
		"app.version":    "string",
		"auth.enabled":   "bool",
		"auth.provider":  "string",
		"features.rateLimit": "bool",
		"features.logging":   "bool",
	},
}

// deepMerge merges src into dst recursively, only for keys already in dst
func deepMerge(dst, src map[string]interface{}) map[string]interface{} {
	for key, srcVal := range src {
		if dstVal, exists := dst[key]; exists {
			if dstMap, ok := dstVal.(map[string]interface{}); ok {
				if srcMap, ok := srcVal.(map[string]interface{}); ok {
					dst[key] = deepMerge(dstMap, srcMap)
					continue
				}
			}
			dst[key] = srcVal
		}
	}
	return dst
}

// setNestedValue sets a value at a dot-separated path
func setNestedValue(data map[string]interface{}, path string, value interface{}) {
	parts := strings.Split(path, ".")
	current := data
	for i := 0; i < len(parts)-1; i++ {
		if next, ok := current[parts[i]]; ok {
			if nextMap, ok := next.(map[string]interface{}); ok {
				current = nextMap
			} else {
				newMap := make(map[string]interface{})
				current[parts[i]] = newMap
				current = newMap
			}
		} else {
			newMap := make(map[string]interface{})
			current[parts[i]] = newMap
			current = newMap
		}
	}
	current[parts[len(parts)-1]] = value
}

// getNestedValue retrieves a value at a dot-separated path
func getNestedValue(data map[string]interface{}, path string) (interface{}, bool) {
	parts := strings.Split(path, ".")
	current := data
	for i := 0; i < len(parts)-1; i++ {
		if next, ok := current[parts[i]]; ok {
			if nextMap, ok := next.(map[string]interface{}); ok {
				current = nextMap
			} else {
				return nil, false
			}
		} else {
			return nil, false
		}
	}
	val, ok := current[parts[len(parts)-1]]
	return val, ok
}

// validatePath checks if a config path is allowed - always validates against schema
func validatePath(path string) bool {
	_, exists := globalConfig.schema[path]
	return exists
}

func handleConfigUpdate(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var payload map[string]interface{}
	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	globalConfig.mu.Lock()
	defer globalConfig.mu.Unlock()

	// Process flat key-value updates
	if updates, ok := payload["updates"].(map[string]interface{}); ok {
		for path, value := range updates {
			if !validatePath(path) {
				http.Error(w, fmt.Sprintf("Path not allowed: %s", path), http.StatusForbidden)
				return
			}
			setNestedValue(globalConfig.data, path, value)
		}
	}

	// Process merge-style updates (deep merge into existing config)
	if merge, ok := payload["merge"].(map[string]interface{}); ok {
		// Validate top-level keys in merge correspond to known sections
		for key := range merge {
			if _, exists := globalConfig.data[key]; !exists {
				http.Error(w, fmt.Sprintf("Unknown section: %s", key), http.StatusForbidden)
				return
			}
		}
		globalConfig.data = deepMerge(globalConfig.data, merge)
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "updated"})
}

func handleConfigRead(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	path := r.URL.Query().Get("path")
	if path == "" {
		globalConfig.mu.RLock()
		defer globalConfig.mu.RUnlock()
		json.NewEncoder(w).Encode(globalConfig.data)
		return
	}

	globalConfig.mu.RLock()
	defer globalConfig.mu.RUnlock()

	val, ok := getNestedValue(globalConfig.data, path)
	if !ok {
		http.Error(w, "Path not found", http.StatusNotFound)
		return
	}
	json.NewEncoder(w).Encode(map[string]interface{}{"value": val})
}

// isAuthEnabled checks the runtime config to determine if auth is required
func isAuthEnabled() bool {
	globalConfig.mu.RLock()
	defer globalConfig.mu.RUnlock()
	if auth, ok := globalConfig.data["auth"]; ok {
		if authMap, ok := auth.(map[string]interface{}); ok {
			if enabled, ok := authMap["enabled"]; ok {
				if b, ok := enabled.(bool); ok {
					return b
				}
			}
		}
	}
	return true
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if isAuthEnabled() {
			token := r.Header.Get("Authorization")
			expected := "Bearer " + os.Getenv("API_SECRET")
			if subtle.ConstantTimeCompare([]byte(token), []byte(expected)) != 1 {
				http.Error(w, "Unauthorized", http.StatusUnauthorized)
				return
			}
		}
		next(w, r)
	}
}

func handleProtected(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"data": "sensitive-information-here"})
}

func main() {
	http.HandleFunc("/config", authMiddleware(handleConfigUpdate))
	http.HandleFunc("/config/read", authMiddleware(handleConfigRead))
	http.HandleFunc("/api/data", authMiddleware(handleProtected))

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Server starting on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
